import { test, expect } from '@playwright/test';

test.describe('Product Sort by Price - Cheapest First', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
    await page.waitForLoadState('networkidle');
  });

  test('should sort products by price in ascending order when selecting "lohi" from sort dropdown', async ({ page }) => {
    // Login as standard_user
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });
    await page.route('**/api/auth/login', (route) => {
      route.abort('failed');
    });
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });
    await page.route('**/api/auth/login', (route) => {
      route.abort('failed');
    });
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });
    await page.route('**/api/auth/login', (route) => {
      route.abort('failed');
    });
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });
    await page.route('**/api/auth/login', (route) => {
      route.abort('failed');
    });
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    await page.route('**/api/auth/login', (route) => {
      route.abort('failed');
    });

    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    await page.route('**/api/auth/login', (route) => {
      route.abort('failed');
    });

    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    await page.route('**/api/auth/login', (route) => {
      route.abort('failed');
    });

    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    await page.route('**/api/auth/login', (route) => {
      route.abort('failed');
    });

    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    // Fill login form
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('standard_user@saucedemo.com');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('secret_sauce');

    const loginButton = page.getByRole('button', { name: /log in/i });
    await loginButton.click();

    // Wait for login success
    await page.waitForURL('**/dashboard');

    // Verify welcome message
    const welcomeMessage = page.getByText(/Welcome, standard_user/i);
    await expect(welcomeMessage).toBeVisible();

    // Navigate to product list
    await page.goto('/products');

    // Verify products are displayed
    const productList = page.getByTestId('product-list');
    await expect(productList).toBeVisible();

    // Verify sort dropdown is visible
    const sortDropdown = page.getByRole('combobox', { name: /sort by price/i });
    await expect(sortDropdown).toBeVisible();

    // Select "lohi" option
    const lohiOption = page.getByRole('option', { name: /lohi/i });
    await lohiOption.click();

    // Verify products are sorted by price
    const firstProductPrice = page.getByTestId('inventory_item_price').first();
    const firstProductPriceValue = await firstProductPrice.evaluate((el) => parseFloat(el.textContent.replace(/[^0-9.]/g, '')));
    const secondProductPrice = page.getByTestId('inventory_item_price').nth(1);
    const secondProductPriceValue = await secondProductPrice.evaluate((el) => parseFloat(el.textContent.replace(/[^0-9.]/g, '')));

    await expect(firstProductPriceValue).toBeLessThan(secondProductPriceValue);

    // Verify list is reordered
    const productItems = page.locator('[data-testid="product-item"]');
    const productCount = await productItems.count();
    await expect(productCount).toBeGreaterThan(0);
  });

  test('should handle empty product list when no items are available', async ({ page }) => {
    // Navigate to product list
    await page.goto('/products');

    // Verify empty list message
    const emptyListMessage = page.getByText(/No products found/i);
    await expect(emptyListMessage).toBeVisible();

    // Verify no products are displayed
    const productList = page.getByTestId('product-list');
    await expect(productList).not.toBeVisible();

    // Verify sort dropdown is still visible
    const sortDropdown = page.getByRole('combobox', { name: /sort by price/i });
    await expect(sortDropdown).toBeVisible();

    // Verify no products are listed
    const productItems = page.locator('[data-testid="product-item"]');
    const productCount = await productItems.count();
    await expect(productCount).toBe(0);
  });
});
